/**
 * Drużyna Andrzeja — public read-only catalog served from the main GitHub branch.
 * Data is generated by GitHub Actions, not by visitor requests.
 * An explicit path allowlist prevents an open proxy.
 */
const ORIGIN = "https://raw.githubusercontent.com/elconcept/druzyna-andrzeja/main";
const ASSETS = Object.freeze({
  "/": ["/web/index.html", "text/html; charset=utf-8"],
  "/index.html": ["/web/index.html", "text/html; charset=utf-8"],
  "/app.js": ["/web/app.js", "application/javascript; charset=utf-8"],
  "/styles.css": ["/web/styles.css", "text/css; charset=utf-8"],
  "/data/proposals.json": ["/catalog/proposals.json", "application/json; charset=utf-8"],
});
addEventListener("fetch", (event) => event.respondWith(serve(event.request)));
async function serve(request) {
  if (request.method !== "GET" && request.method !== "HEAD") {
    return new Response("Method Not Allowed", { status: 405, headers: { Allow: "GET, HEAD" } });
  }
  const url = new URL(request.url);
  const asset = ASSETS[url.pathname];
  if (!asset) return new Response("Not Found", { status: 404 });
  let upstream;
  try {
    upstream = await fetch(ORIGIN + asset[0], {
      method: "GET",
      headers: { "User-Agent": "druzyna-andrzeja-public-catalog" },
      cf: { cacheEverything: true, cacheTtl: 300 },
    });
  } catch (error) {
    return new Response("Repository source temporarily unavailable", { status: 502 });
  }
  if (!upstream.ok) return new Response("Catalog source unavailable", { status: 502 });
  const headers = new Headers({
    "Content-Type": asset[1],
    "Cache-Control": "public, max-age=120, s-maxage=300",
    "X-Content-Type-Options": "nosniff",
    "Referrer-Policy": "strict-origin-when-cross-origin",
    "X-Frame-Options": "DENY",
    "Permissions-Policy": "camera=(), microphone=(), geolocation=()",
    "X-Druzyna-Source": "elconcept/druzyna-andrzeja:main",
  });
  if (asset[1].startsWith("text/html")) {
    headers.set("Content-Security-Policy",
      "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' data:; font-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'");
  }
  return new Response(request.method === "HEAD" ? null : upstream.body, {
    status: 200,
    headers,
  });
}
